    def branch_dist_lt(a, b):
        if a < b: return 0.0
        else: return a - b + epsilon # a >= b, need to decrease a or increase b

    # Helper for a >= b (target is a >= b)
    # Returns 0 if a >= b is true, positive if false.
    def branch_dist_ge(a, b):
        if a >= b: return 0.0
        else: return b - a + epsilon # a < b, need to increase a or decrease b

    # Helper for a > b (target is a > b)
    # Returns 0 if a > b is true, positive if false.
