    bd_len_lt_2_false = max(0, 2 - len_nums)

    # Branch distance for nums == sorted(nums)
    # Sum of absolute differences for list equality
    bd_nums_eq_sorted_true = 0.0
    if len_nums > 0:
        sorted_nums = sorted(nums)
        for i in range(len_nums):
            bd_nums_eq_sorted_true += abs(nums[i] - sorted_nums[i])

    # Distance for nums != sorted(nums) (False branch of nums == sorted(nums))
    # If nums is already not sorted (bd_nums_eq_sorted_true > 0), distance is 0.
    # If sorted (bd_nums_eq_sorted_true == 0), distance is 1.0 (to make it not sorted).
    bd_nums_eq_sorted_false = 0.0 if bd_nums_eq_sorted_true > 0 else 1.0

    # Branch distance for len(nums) != len(set(nums)) (i.e., has duplicates)
    len_unique_nums = len(set(nums))
    is_distinct = (len_nums == len_unique_nums)

    # Distance for len(nums) != len(set(nums)) to be True (has duplicates)
    # If it has duplicates (!is_distinct), distance is 0. If distinct (is_distinct), distance is 1.0.
    bd_has_duplicates_true = 1.0 if is_distinct else 0.0

    # Distance for len(nums) == len(set(nums)) to be True (is unique/distinct)
