# ================================================================================

TARGETS_pin_pattern = ["secret_pin", "all_same", "ordered_sum_20", "other"]

def fitness_pin_pattern(chromosome, target):
    a, b, c, d = chromosome

    # Helper conditions to determine which branch would be taken by the original function
    # These evaluate the truthiness of the original conditions, without branch distance.
    secret_pin_condition_met = (a == 7 and b == 3 and c == 9 and d == 1)
    all_same_condition_met = (a == b and b == c and c == d)
    ordered_sum_20_condition_met = (a + b + c + d == 20 and a < b and b < c and c < d)

    if target == "secret_pin":
        # Target: a == 7 and b == 3 and c == 9 and d == 1
        dist_a = abs(a - 7)
        dist_b = abs(b - 3)
        dist_c = abs(c - 9)
        dist_d = abs(d - 1)
        return dist_a + dist_b + dist_c + dist_d

    elif target == "all_same":
        # Target: a == b == c == d AND NOT secret_pin_condition_met
        dist_ab = abs(a - b)
        dist_bc = abs(b - c)
        dist_cd = abs(c - d)
        
        fitness_val = dist_ab + dist_bc + dist_cd
        
        # Add a penalty if the higher-priority "secret_pin" condition is met,
        # because the original function would return "secret_pin" in that case.
        if secret_pin_condition_met:
            fitness_val += 1
        return fitness_val

    elif target == "ordered_sum_20":
        # Target: a + b + c + d == 20 AND a < b < c < d
        # AND NOT secret_pin_condition_met AND NOT all_same_condition_met
        dist_sum = abs(a + b + c + d - 20)
        dist_order_ab = max(0, a - b + 1)
        dist_order_bc = max(0, b - c + 1)
        dist_order_cd = max(0, c - d + 1)
        
        fitness_val = dist_sum + dist_order_ab + dist_order_bc + dist_order_cd
        
        # Add penalties if higher-priority conditions are met
        if secret_pin_condition_met:
            fitness_val += 1
        # Use elif to reflect the original function's branch priority
        elif all_same_condition_met:
            fitness_val += 1
        return fitness_val

    elif target == "other":
        # Target: ELSE branch, meaning NOT secret_pin_condition_met 
        # AND NOT all_same_condition_met AND NOT ordered_sum_20_condition_met
        fitness_val = 0
        if secret_pin_condition_met:
            fitness_val += 1
        elif all_same_condition_met:
            fitness_val += 1
        elif ordered_sum_20_condition_met:
            fitness_val += 1
        return fitness_val

    else:
        raise ValueError(f"Unknown target: {target}")

