# Original function: shipping_discount
# Fitness function: fitness_shipping_discount
# LLM targets: ['invalid', 'free_express_shipping', 'standard_discount', 'small_discount', 'no_discount']
# Notes: The fitness function uses branch distance to guide the search towards the target return statements. It first checks if the target is already achieved, returning 0.0 if so. Otherwise, it calculates the sum of distances required to falsify all preceding conditions in the control flow and then satisfy the specific condition leading to the target return. Helper functions are used to calculate distances for various comparison operators and boolean values, ensuring positive non-zero distances when a condition is not met.
# ================================================================================

def _dist_lt(a, b): # Distance to make a < b true
    if a < b: return 0.0
    return float(a - b + 1)

def _dist_le(a, b): # Distance to make a <= b true
    if a <= b: return 0.0
    return float(a - b + 1)

def _dist_gt(a, b): # Distance to make a > b true
    if a > b: return 0.0
    return float(b - a + 1)

def _dist_ge(a, b): # Distance to make a >= b true
    if a >= b: return 0.0
    return float(b - a + 1)

def _dist_bool_true(val): # Distance to make val true
    return 0.0 if val else 1.0

def _dist_bool_false(val): # Distance to make val false
    return 0.0 if not val else 1.0

def fitness_shipping_discount(chromosome, target):
    order_total, distance, is_member = chromosome

    # Evaluate original function's branches to return 0 if target is met
    # This part ensures that if target is reached, fitness is exactly 0.
    if order_total < 0 or distance < 0:
        if target == "invalid": return 0.0
    elif order_total >= 200 and distance <= 50 and is_member:
        if target == "free_express_shipping": return 0.0
    elif order_total >= 100 and distance <= 100:
        if target == "standard_discount": return 0.0
    elif order_total >= 50 or is_member:
        if target == "small_discount": return 0.0
    else: # Covers "no_discount"
        if target == "no_discount": return 0.0

    # If target not met, calculate branch distance

    # C1: order_total < 0 or distance < 0
    dist_c1_true = min(_dist_lt(order_total, 0), _dist_lt(distance, 0))
    # Need to make (order_total >= 0 AND distance >= 0) true
    dist_c1_false = _dist_ge(order_total, 0) + _dist_ge(distance, 0)

    # C2: order_total >= 200 and distance <= 50 and is_member
    dist_c2_true = _dist_ge(order_total, 200) + _dist_le(distance, 50) + _dist_bool_true(is_member)
    # Need to make (order_total < 200 OR distance > 50 OR not is_member) true
    dist_c2_false = min(_dist_lt(order_total, 200), _dist_gt(distance, 50), _dist_bool_false(is_member))

    # C3: order_total >= 100 and distance <= 100
    dist_c3_true = _dist_ge(order_total, 100) + _dist_le(distance, 100)
    # Need to make (order_total < 100 OR distance > 100) true
    dist_c3_false = min(_dist_lt(order_total, 100), _dist_gt(distance, 100))

    # C4: order_total >= 50 or is_member
    dist_c4_true = min(_dist_ge(order_total, 50), _dist_bool_true(is_member))
    # Need to make (order_total < 50 AND not is_member) true
    dist_c4_false = _dist_lt(order_total, 50) + _dist_bool_false(is_member)

    if target == "invalid":
        return dist_c1_true

    elif target == "free_express_shipping":
        return dist_c1_false + dist_c2_true

    elif target == "standard_discount":
        return dist_c1_false + dist_c2_false + dist_c3_true

    elif target == "small_discount":
        return dist_c1_false + dist_c2_false + dist_c3_false + dist_c4_true

    elif target == "no_discount":
        return dist_c1_false + dist_c2_false + dist_c3_false + dist_c4_false

    else:
        raise ValueError("Unknown target: " + target)

