# LLM targets: ['positive', 'negative', 'zero']
# Notes: The fitness function aims to drive 'x' towards the target condition. For 'positive' (x > 0), it minimizes `1 - x` if `x <= 0`. For 'negative' (x < 0), it minimizes `1 + x` if `x >= 0`. For 'zero' (x == 0), it minimizes the absolute value of `x`.
# ================================================================================

TARGETS_sign_type = ["positive", "negative", "zero"]

def fitness_sign_type(chromosome, target):
    x = chromosome[0]

    if target == "positive":
        # Target: x > 0
        # If x <= 0, distance is 1 - x (e.g., if x=0, dist=1; if x=-1, dist=2)
        return max(0, 1 - x)
    elif target == "negative":
        # Target: x < 0
        # If x >= 0, distance is 1 + x (e.g., if x=0, dist=1; if x=1, dist=2)
        return max(0, 1 + x)
    elif target == "zero":
        # Target: x == 0
        # If x != 0, distance is abs(x)
        return abs(x)
    else:
        raise ValueError(f"Unknown target: {target}")

