# Fitness function: fitness_string_category
# LLM targets: ['empty', 'long_palindrome', 'short_palindrome', 'long_non_palindrome', 'other']
# Notes: The fitness function calculates the branch distance for each condition in the if/elif/else chain. It sums up the distances required to satisfy the conditions for a specific target path. For string equality/inequality, a distance of 0 is returned if the condition is met, and 1 otherwise. For numeric comparisons, standard branch distance calculation `max(0, B - A + 1)` or `max(0, A - B)` is used. An implicit condition `len(s) != 0` is added to branches following the initial `if len(s) == 0:`.
# ================================================================================

TARGETS_string_category = ["empty", "long_palindrome", "short_palindrome", "long_non_palindrome", "other"]

def fitness_string_category(chromosome, target):
    s = chromosome[0]
    s_len = len(s)
    is_palindrome = (s == s[::-1])

    # Distances to make conditions true
    # Condition: len(s) == 0
    dist_len_eq_0 = abs(s_len - 0)
    # Condition: len(s) != 0 (penalty if len(s) is 0)
    dist_len_ne_0 = 1 if s_len == 0 else 0

    # Condition: s == s[::-1]
    dist_is_palindrome = 0 if is_palindrome else 1
    # Condition: s != s[::-1]
    dist_not_is_palindrome = 1 if is_palindrome else 0

    # Condition: len(s) > 3
    dist_len_gt_3 = max(0, 3 - s_len + 1)
    # Condition: len(s) <= 3
    dist_len_le_3 = max(0, s_len - 3)

    # Condition: len(s) > 5
    dist_len_gt_5 = max(0, 5 - s_len + 1)
    # Condition: len(s) <= 5
    dist_len_le_5 = max(0, s_len - 5)

    if target == "empty":
        # Path: len(s) == 0
        return dist_len_eq_0
    elif target == "long_palindrome":
        # Path: len(s) != 0 AND s == s[::-1] AND len(s) > 3
        return dist_len_ne_0 + dist_is_palindrome + dist_len_gt_3
    elif target == "short_palindrome":
        # Path: len(s) != 0 AND s == s[::-1] AND NOT (len(s) > 3) (i.e., len(s) <= 3)
        return dist_len_ne_0 + dist_is_palindrome + dist_len_le_3
    elif target == "long_non_palindrome":
        # Path: len(s) != 0 AND NOT (s == s[::-1]) AND len(s) > 5
        return dist_len_ne_0 + dist_not_is_palindrome + dist_len_gt_5
    elif target == "other":
        # Path: len(s) != 0 AND NOT (s == s[::-1]) AND NOT (len(s) > 5) (i.e., len(s) <= 5)
        return dist_len_ne_0 + dist_not_is_palindrome + dist_len_le_5
    else:
        raise ValueError("Unknown target: " + target)

# ================================================================================
# Original function: transaction_pattern
# Fitness function: fitness_transaction_pattern
# LLM targets: ['empty', 'contains_zero', 'many_large_deposits', 'many_large_withdrawals', 'mixed_transactions', 'simple_pattern']
# Notes: The fitness function guides towards different transaction patterns. It prioritizes achieving non-empty lists first, then lists without zeros, and finally, the specific counts and sums of positive and negative amounts to satisfy each target's conditions. For the 'simple_pattern' (default branch), it guides towards inputs that explicitly fail the conditions for all other specific return paths.
# ================================================================================

def fitness_transaction_pattern(chromosome, target):
    amounts = chromosome[0]

    # Helper for branch distance calculation for numeric comparisons
    def _compute_distance_numeric(actual, target_val, operator):
        if operator == "==": return abs(actual - target_val)
        if operator == "!=": return 0 if actual != target_val else 1
        if operator == ">": return max(0, target_val - actual + 1)
        if operator == ">=": return max(0, target_val - actual)
        if operator == "<": return max(0, actual - target_val + 1)
        if operator == "<=": return max(0, actual - target_val)
        return 1000000 # Fallback for unknown operator, should not happen

    if target == "empty":
        return _compute_distance_numeric(len(amounts), 0, "==")

    # All subsequent targets require amounts not to be empty
    dist_not_empty = _compute_distance_numeric(len(amounts), 0, "!=")
    if dist_not_empty > 0:
        # If amounts is empty, we can't satisfy conditions for other branches
        # Add a large constant to make distance positive and prioritize len(amounts) != 0
        if target != "empty": # Only for non-"empty" targets
            return dist_not_empty + 1000000

    # Pre-calculations for 'contains_zero' and subsequent targets
    has_zero_in_amounts = False
    min_abs_val_if_no_zero = 0.0 # Will store minimum absolute value of non-zero elements
    if len(amounts) > 0: # Ensure amounts is not empty before iterating
        # Initialize with a value larger than any possible element's abs value (given -100 to 100)
        min_abs_val_if_no_zero_current = 101.0
        found_non_zero = False
        for x in amounts:
            if x == 0:
                has_zero_in_amounts = True
                # If a zero is found, distance to 'any(x==0)' is 0, so we can stop searching for min_abs_val
                min_abs_val_if_no_zero_current = 0.0
                break
            else:
                found_non_zero = True
                min_abs_val_if_no_zero_current = min(min_abs_val_if_no_zero_current, abs(x))
        if found_non_zero: # Only assign if there was at least one non-zero element
            min_abs_val_if_no_zero = min_abs_val_if_no_zero_current
        else: # All elements were zero (and has_zero_in_amounts is True)
            min_abs_val_if_no_zero = 0.0

    if target == "contains_zero":
        dist_has_zero = 0.0
        if not has_zero_in_amounts:
            dist_has_zero = min_abs_val_if_no_zero + 1.0 # Add 1 to ensure positive fitness if no zero
        return dist_has_zero

    # For targets after 'contains_zero', we must not contain zero.
    # Distance to NOT have zero.
    dist_not_contains_zero = 0.0
    if has_zero_in_amounts:
        dist_not_contains_zero = min_abs_val_if_no_zero + 1.0
    if dist_not_contains_zero > 0 and target not in ["empty", "contains_zero"]:
        return dist_not_contains_zero + 1000000 # Prioritize not having zero

    # Calculate positives, negatives, total for subsequent branches (assuming no empty, no zero)
    positives = 0
    negatives = 0
    total = 0
    for x in amounts:
        if x > 0:
            positives += 1
        elif x < 0:
            negatives += 1
        total += x

    if target == "many_large_deposits":
        f_positives = _compute_distance_numeric(positives, 3, ">=")
        f_negatives = _compute_distance_numeric(negatives, 0, "==")
        f_total = _compute_distance_numeric(total, 100, ">")
        return f_positives + f_negatives + f_total

    if target == "many_large_withdrawals":
        f_negatives = _compute_distance_numeric(negatives, 2, ">=")
        f_total = _compute_distance_numeric(total, -50, "<")
        return f_negatives + f_total

    if target == "mixed_transactions":
        f_positives = _compute_distance_numeric(positives, 0, ">")
        f_negatives = _compute_distance_numeric(negatives, 0, ">")
        return f_positives + f_negatives

    if target == "simple_pattern":
        # For 'simple_pattern', none of the specific conditions for the other return paths must be met.

        # Distance to NOT take 'many_large_deposits' branch
        # Condition: positives >= 3 and negatives == 0 and total > 100
        # Negated: (positives < 3) OR (negatives != 0) OR (total <= 100)
        f_not_deposits = min(
            _compute_distance_numeric(positives, 3, "<"),
            _compute_distance_numeric(negatives, 0, "!="),
            _compute_distance_numeric(total, 100, "<=")
        )

        # Distance to NOT take 'many_large_withdrawals' branch
        # Condition: negatives >= 2 and total < -50
        # Negated: (negatives < 2) OR (total >= -50)
        f_not_withdrawals = min(
            _compute_distance_numeric(negatives, 2, "<"),
            _compute_distance_numeric(total, -50, ">=")
        )

        # Distance to NOT take 'mixed_transactions' branch
        # Condition: positives > 0 and negatives > 0
        # Negated: (positives == 0) OR (negatives == 0)
        f_not_mixed = min(
            _compute_distance_numeric(positives, 0, "=="),
            _compute_distance_numeric(negatives, 0, "==")
        )

        return f_not_deposits + f_not_withdrawals + f_not_mixed

    raise ValueError("Unknown target: " + target)

TARGETS_transaction_pattern = [
    "empty",
    "contains_zero",
    "many_large_deposits",
    "many_large_withdrawals",
    "mixed_transactions",
    "simple_pattern"
]

# ================================================================================
# Original function: triangle_type
# Fitness function: fitness_triangle_type
# LLM targets: ['invalid_side', 'not_triangle', 'equilateral', 'isosceles', 'scalene']
# Notes: The fitness function calculates branch distances for each condition. For compound conditions (OR/AND), it minimizes/sums distances respectively. To reach a specific target, it sums the branch distances to falsify all preceding conditions in the control flow and the branch distance to satisfy the target condition.
# ================================================================================

TARGETS_triangle_type = ["invalid_side", "not_triangle", "equilateral", "isosceles", "scalene"]

def fitness_triangle_type(chromosome, target):
    a, b, c = chromosome
    k = 1 # Small constant for strict inequalities

    # Helper functions for branch distance
    # Returns 0 if the condition is met, positive otherwise.
    # Smaller positive values indicate closer to satisfying the condition.
    def bd_eq(x, y): # Target x == y
        return abs(x - y)

    def bd_neq(x, y): # Target x != y
        return max(0, k - abs(x - y))

    def bd_lt(x, y): # Target x < y
        return max(0, x - y + k)

    def bd_le(x, y): # Target x <= y
        return max(0, x - y)

    def bd_gt(x, y): # Target x > y
        return max(0, y - x + k)

    def bd_ge(x, y): # Target x >= y
        return max(0, y - x)

    if target not in TARGETS_triangle_type:
        raise ValueError(f"Unknown target: {target}")

    path_distance = 0.0

    # --- First condition: a <= 0 or b <= 0 or c <= 0 -> "invalid_side" ---
    # Distances to make (a <= 0) true, (b <= 0) true, (c <= 0) true
    d_a_le_0_T = bd_le(a, 0)
    d_b_le_0_T = bd_le(b, 0)
    d_c_le_0_T = bd_le(c, 0)
    
    # To satisfy `a <= 0 or b <= 0 or c <= 0` (OR condition)
    bd_cond1_T = min(d_a_le_0_T, d_b_le_0_T, d_c_le_0_T)
    
    # To falsify `a <= 0 or b <= 0 or c <= 0` (i.e., `a > 0 and b > 0 and c > 0`)
    # Sum of distances to make each sub-condition true for falsification
    bd_cond1_F = bd_gt(a, 0) + bd_gt(b, 0) + bd_gt(c, 0)

    if target == "invalid_side":
        return bd_cond1_T
    
    # If the target is not "invalid_side", we must falsify cond1
    path_distance += bd_cond1_F

    # --- Second condition: a + b <= c or a + c <= b or b + c <= a -> "not_triangle" ---
    # Distances to make each sub-condition true
    d_ab_le_c_T = bd_le(a + b, c)
    d_ac_le_b_T = bd_le(a + c, b)
    d_bc_le_a_T = bd_le(b + c, a)

    # To satisfy `a + b <= c or a + c <= b or b + c <= a` (OR condition)
    bd_cond2_T = min(d_ab_le_c_T, d_ac_le_b_T, d_bc_le_a_T)

    # To falsify `a + b <= c or a + c <= b or b + c <= a`
    # (i.e., `a + b > c and a + c > b and b + c > a`)
    bd_cond2_F = bd_gt(a + b, c) + bd_gt(a + c, b) + bd_gt(b + c, a)

    if target == "not_triangle":
        return path_distance + bd_cond2_T
    
    # If the target is not "not_triangle", we must falsify cond2
    path_distance += bd_cond2_F

    # --- Third condition: a == b and b == c -> "equilateral" ---
    # Distances to make each sub-condition true
    d_a_eq_b_T = bd_eq(a, b)
    d_b_eq_c_T = bd_eq(b, c)

    # To satisfy `a == b and b == c` (AND condition)
    bd_cond3_T = d_a_eq_b_T + d_b_eq_c_T

    # To falsify `a == b and b == c` (i.e., `a != b or b != c`)
    bd_cond3_F = min(bd_neq(a, b), bd_neq(b, c))

    if target == "equilateral":
        return path_distance + bd_cond3_T
    
    # If the target is not "equilateral", we must falsify cond3
    path_distance += bd_cond3_F

    # --- Fourth condition: a == b or a == c or b == c -> "isosceles" ---
    # Distances to make each sub-condition true
    d_a_eq_b_isosceles_T = bd_eq(a, b)
    d_a_eq_c_isosceles_T = bd_eq(a, c)
    d_b_eq_c_isosceles_T = bd_eq(b, c)

    # To satisfy `a == b or a == c or b == c` (OR condition)
    bd_cond4_T = min(d_a_eq_b_isosceles_T, d_a_eq_c_isosceles_T, d_b_eq_c_isosceles_T)

    # To falsify `a == b or a == c or b == c`
    # (i.e., `a != b and a != c and b != c`)
    bd_cond4_F = bd_neq(a, b) + bd_neq(a, c) + bd_neq(b, c)

    if target == "isosceles":
        return path_distance + bd_cond4_T
    
    # If the target is not "isosceles", we must falsify cond4
    path_distance += bd_cond4_F

    # --- Fifth (else) branch: "scalene" ---
    # This branch is reached if all preceding conditions are falsified
    if target == "scalene":
        return path_distance
    
    # Should not be reached due to initial target check
    return float('inf')

# ================================================================================
# Original function: username_category
# Fitness function: fitness_username_category
# LLM targets: ['empty', 'too_short', 'starts_with_digit', 'strong_username', 'medium_username', 'weak_username']
# Notes: This fitness function calculates branch distances for each return path. It accumulates distances from conditions that must be false to reach a target and adds distances for conditions that must be true for the target itself. For compound conditions (AND), to make the condition true, distances for each sub-condition are summed. To make an AND condition false, the minimum distance to make any one of its sub-conditions false is used. Helper functions are used for common comparison types and boolean conditions.
# ================================================================================

TARGETS_username_category = ["empty", "too_short", "starts_with_digit", "strong_username", "medium_username", "weak_username"]

def fitness_username_category(chromosome, target):
    username = chromosome[0]
    len_username = len(username)

    def _dist_true_eq(a, b): return abs(a - b)
    def _dist_false_eq(a, b): return 0 if a != b else 1
    def _dist_true_lt(a, b): return max(0, a - b + 1)
    def _dist_false_lt(a, b): return max(0, b - a)
    def _dist_true_ge(a, b): return max(0, b - a)
    def _dist_false_ge(a, b): return max(0, a - b + 1)
    def _dist_true_bool(b_val): return 0 if b_val else 1
    def _dist_false_bool(b_val): return 0 if not b_val else 1

    has_digit = any(ch.isdigit() for ch in username)
    has_upper = any(ch.isupper() for ch in username)
    has_special = any(not ch.isalnum() for ch in username)

    fitness = 0

    if target == "empty":
        fitness += _dist_true_eq(len_username, 0)
        return fitness

    fitness += _dist_false_eq(len_username, 0)

    if target == "too_short":
        fitness += _dist_true_lt(len_username, 5)
        return fitness

    fitness += _dist_false_lt(len_username, 5)

    if target == "starts_with_digit":
        p3_is_digit = False
        if len_username > 0:
            p3_is_digit = username[0].isdigit()
        fitness += _dist_true_bool(p3_is_digit)
        return fitness

    p3_is_digit = False
    if len_username > 0:
        p3_is_digit = username[0].isdigit()
    fitness += _dist_false_bool(p3_is_digit)

    if target == "strong_username":
        fitness += _dist_true_ge(len_username, 10)
        fitness += _dist_true_bool(has_digit)
        fitness += _dist_true_bool(has_upper)
        fitness += _dist_true_bool(has_special)
        return fitness

    dist_false_p4_len = _dist_false_ge(len_username, 10)
    dist_false_p4_digit = _dist_false_bool(has_digit)
    dist_false_p4_upper = _dist_false_bool(has_upper)
    dist_false_p4_special = _dist_false_bool(has_special)
    fitness += min(dist_false_p4_len, dist_false_p4_digit, dist_false_p4_upper, dist_false_p4_special)

    if target == "medium_username":
        fitness += _dist_true_bool(has_digit)
        fitness += _dist_true_bool(has_upper)
        return fitness

    dist_false_p5_digit = _dist_false_bool(has_digit)
    dist_false_p5_upper = _dist_false_bool(has_upper)
    fitness += min(dist_false_p5_digit, dist_false_p5_upper)

    if target == "weak_username":
        return fitness

    raise ValueError(f"Unknown target: {target}")

# ================================================================================
# Unified fitness interface
# ================================================================================

def evaluate_fitness(function_name, chromosome, target):
    if function_name == 'bmi_category':
        return fitness_bmi_category(chromosome, target)
    elif function_name == 'list_pattern':
        return fitness_list_pattern(chromosome, target)
    elif function_name == 'number_kind':
        return fitness_number_kind(chromosome, target)
    elif function_name == 'password_strength':
        return fitness_password_strength(chromosome, target)
    elif function_name == 'pin_pattern':
        return fitness_pin_pattern(chromosome, target)
    elif function_name == 'shipping_discount':
        return fitness_shipping_discount(chromosome, target)
    elif function_name == 'sign_type':
        return fitness_sign_type(chromosome, target)
    elif function_name == 'string_category':
        return fitness_string_category(chromosome, target)
    elif function_name == 'transaction_pattern':
        return fitness_transaction_pattern(chromosome, target)
    elif function_name == 'triangle_type':
        return fitness_triangle_type(chromosome, target)
    elif function_name == 'username_category':
        return fitness_username_category(chromosome, target)
    else:
        raise ValueError(f'Unknown function name: {function_name}')
